window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a43c499d2ba1ab54"]={"versions": [{"id": "FIG-a43c499d2ba1ab54", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Server-Antwortverhaltens im AUTOSAR-Basissoftwaremodul Service Discovery (<code>Sd</code>) innerhalb des AUTOSAR-Kommunikationsstacks (Classic Platform). Das Diagramm stellt die interne Verarbeitung empfangener SD-Nachrichten und die Vorbereitung von Antwortnachrichten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>«module» Sd</code>: AUTOSAR Service Discovery Basissoftwaremodul (zentrale aktive Lebenslinie, führt die Verarbeitungslogik aus).</li>\n<li><code>«module» SoAd</code>: Socket Adapter Basissoftwaremodul (passive Lebenslinie im Diagramm, an der keine Interaktionspfeile ansetzen oder enden).</li>\n<li>Interne Methoden / Selbstaufrufe auf <code>Sd</code>:</li>\n<li><code>disassembleIncomingMessage() :entries, options</code>: Dekodierung und Zerlegung der eingehenden SD-Botschaft in Einträge und Optionen.</li>\n<li><code>buildOfferServiceEntry()</code>: Erstellung eines OfferService-Eintrags.</li>\n<li><code>determineRequestResponseDelay(SdServerTimerRequestResponseMinDelay, SdServerTimerRequestResponseMaxDelay)</code>: Ermittlung der zufälligen oder parametrierten Antwortverzögerung.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\"+delay)</code>: Einreihen des OfferService in die Sendewarteschlange mit berechneter Verzögerung.</li>\n<li><code>addClientToFanOut()</code>: Hinzufügen des anfragenden Clients zur Fan-Out-Liste der Eventgruppe.</li>\n<li><code>buildSubscribeAckEntry()</code>: Erstellung eines SubscribeEventgroupAck-Eintrags.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\")</code>: Sofortiges Einreihen der Bestätigung in die Sendewarteschlange.</li>\n<li><code>removeClientFromFanOut()</code>: Entfernen des abmeldenden Clients aus der Fan-Out-Liste der Eventgruppe.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Zu Beginn zerlegt <code>Sd</code> eine eingegangene Nachricht über den Selbstaufruf <code>disassembleIncomingMessage() :entries, options</code>.</li>\n<li>Über ein <code>alt</code>-Fragment (<code>alt over received entries</code>) wird sequenziell über die empfangenen Einträge verzweigt:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==FindService]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if entry is in Main Phase and entry is available</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>buildOfferServiceEntry()</code> wird aufgerufen.</li>\n<li><code>determineRequestResponseDelay(SdServerTimerRequestResponseMinDelay, SdServerTimerRequestResponseMaxDelay)</code> bestimmt die Verzögerung.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\"+delay)</code> reiht den Eintrag mit Verzögerung ein.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==SubscribeEventgroup]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if eventgroup entry is available</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>addClientToFanOut()</code> registriert den Client.</li>\n<li><code>buildSubscribeAckEntry()</code> erzeugt das Subscribe-Ack.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\")</code> reiht die Bestätigung ohne Verzögerung (<code>sendTime=\"now\"</code>) in die Sendewarteschlange ein.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==StopSubscribeEventgroup]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if client is subscribed</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>removeClientFromFanOut()</code> deregistriert den Client aus dem Fan-Out.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[else]</code>:</li>\n<li>Keine Aktion definiert (stilles Verwerfen / Übergehen nicht passender Einträge).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Spezifiziert das normative Reaktionsverhalten des SD-Servers auf FindService-, SubscribeEventgroup- und StopSubscribeEventgroup-Nachrichten.</li>\n<li>Die Antwort auf FindService erfordert die Berücksichtigung von Phasenbedingungen (Main Phase) und die Einhaltung eines parametrierten Jitters/Delays (<code>SdServerTimerRequestResponseMinDelay</code> bis <code>SdServerTimerRequestResponseMaxDelay</code>) zur Vermeidung von Botschaftskollisionen auf dem Netzwerk.</li>\n<li>Eventgruppen-Abonnements erfordern die Pflege von Fan-Out-Tabellen zur Laufzeit; Subscribe-Acks werden im Gegensatz zu OfferService-Antworten unmittelbar (<code>sendTime=\"now\"</code>) eingereiht. StopSubscribe führt zur Entfernung ohne Sendeantwort.</li>\n</ul>"}, {"id": "FIG-e268d6f2d1e8aab3", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Server-Antwortverhaltens im AUTOSAR-Basissoftwaremodul Service Discovery (<code>Sd</code>) innerhalb des AUTOSAR-Kommunikationsstacks (Classic Platform). Das Diagramm stellt die interne Verarbeitung empfangener SD-Nachrichten und die Vorbereitung von Antwortnachrichten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>«module» Sd</code>: AUTOSAR Service Discovery Basissoftwaremodul (zentrale aktive Lebenslinie, führt die Verarbeitungslogik aus).</li>\n<li><code>«module» SoAd</code>: Socket Adapter Basissoftwaremodul (passive Lebenslinie im Diagramm, an der keine Interaktionspfeile ansetzen oder enden).</li>\n<li>Interne Methoden / Selbstaufrufe auf <code>Sd</code>:</li>\n<li><code>disassembleIncomingMessage() :entries, options</code>: Dekodierung und Zerlegung der eingehenden SD-Botschaft in Einträge und Optionen.</li>\n<li><code>buildOfferServiceEntry()</code>: Erstellung eines OfferService-Eintrags.</li>\n<li><code>determineRequestResponseDelay(SdServerTimerRequestResponseMinDelay, SdServerTimerRequestResponseMaxDelay)</code>: Ermittlung der zufälligen oder parametrierten Antwortverzögerung.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\"+delay)</code>: Einreihen des OfferService in die Sendewarteschlange mit berechneter Verzögerung.</li>\n<li><code>addClientToFanOut()</code>: Hinzufügen des anfragenden Clients zur Fan-Out-Liste der Eventgruppe.</li>\n<li><code>buildSubscribeAckEntry()</code>: Erstellung eines SubscribeEventgroupAck-Eintrags.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\")</code>: Sofortiges Einreihen der Bestätigung in die Sendewarteschlange.</li>\n<li><code>removeClientFromFanOut()</code>: Entfernen des abmeldenden Clients aus der Fan-Out-Liste der Eventgruppe.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Zu Beginn zerlegt <code>Sd</code> eine eingegangene Nachricht über den Selbstaufruf <code>disassembleIncomingMessage() :entries, options</code>.</li>\n<li>Über ein <code>alt</code>-Fragment (<code>alt over received entries</code>) wird sequenziell über die empfangenen Einträge verzweigt:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==FindService]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if entry is in Main Phase and entry is available</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>buildOfferServiceEntry()</code> wird aufgerufen.</li>\n<li><code>determineRequestResponseDelay(SdServerTimerRequestResponseMinDelay, SdServerTimerRequestResponseMaxDelay)</code> bestimmt die Verzögerung.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\"+delay)</code> reiht den Eintrag mit Verzögerung ein.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==SubscribeEventgroup]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if eventgroup entry is available</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>addClientToFanOut()</code> registriert den Client.</li>\n<li><code>buildSubscribeAckEntry()</code> erzeugt das Subscribe-Ack.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\")</code> reiht die Bestätigung ohne Verzögerung (<code>sendTime=\"now\"</code>) in die Sendewarteschlange ein.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==StopSubscribeEventgroup]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if client is subscribed</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>removeClientFromFanOut()</code> deregistriert den Client aus dem Fan-Out.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[else]</code>:</li>\n<li>Keine Aktion definiert (stilles Verwerfen / Übergehen nicht passender Einträge).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Spezifiziert das normative Reaktionsverhalten des SD-Servers auf FindService-, SubscribeEventgroup- und StopSubscribeEventgroup-Nachrichten.</li>\n<li>Die Antwort auf FindService erfordert die Berücksichtigung von Phasenbedingungen (Main Phase) und die Einhaltung eines parametrierten Jitters/Delays (<code>SdServerTimerRequestResponseMinDelay</code> bis <code>SdServerTimerRequestResponseMaxDelay</code>) zur Vermeidung von Botschaftskollisionen auf dem Netzwerk.</li>\n<li>Eventgruppen-Abonnements erfordern die Pflege von Fan-Out-Tabellen zur Laufzeit; Subscribe-Acks werden im Gegensatz zu OfferService-Antworten unmittelbar (<code>sendTime=\"now\"</code>) eingereiht. StopSubscribe führt zur Entfernung ohne Sendeantwort.</li>\n</ul>"}, {"id": "FIG-2593068811199b67", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Server-Antwortverhaltens im AUTOSAR-Basissoftwaremodul Service Discovery (<code>Sd</code>) innerhalb des AUTOSAR-Kommunikationsstacks (Classic Platform). Das Diagramm stellt die interne Verarbeitung empfangener SD-Nachrichten und die Vorbereitung von Antwortnachrichten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>«module» Sd</code>: AUTOSAR Service Discovery Basissoftwaremodul (zentrale aktive Lebenslinie, führt die Verarbeitungslogik aus).</li>\n<li><code>«module» SoAd</code>: Socket Adapter Basissoftwaremodul (passive Lebenslinie im Diagramm, an der keine Interaktionspfeile ansetzen oder enden).</li>\n<li>Interne Methoden / Selbstaufrufe auf <code>Sd</code>:</li>\n<li><code>disassembleIncomingMessage() :entries, options</code>: Dekodierung und Zerlegung der eingehenden SD-Botschaft in Einträge und Optionen.</li>\n<li><code>buildOfferServiceEntry()</code>: Erstellung eines OfferService-Eintrags.</li>\n<li><code>determineRequestResponseDelay(SdServerTimerRequestResponseMinDelay, SdServerTimerRequestResponseMaxDelay)</code>: Ermittlung der zufälligen oder parametrierten Antwortverzögerung.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\"+delay)</code>: Einreihen des OfferService in die Sendewarteschlange mit berechneter Verzögerung.</li>\n<li><code>addClientToFanOut()</code>: Hinzufügen des anfragenden Clients zur Fan-Out-Liste der Eventgruppe.</li>\n<li><code>buildSubscribeAckEntry()</code>: Erstellung eines SubscribeEventgroupAck-Eintrags.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\")</code>: Sofortiges Einreihen der Bestätigung in die Sendewarteschlange.</li>\n<li><code>removeClientFromFanOut()</code>: Entfernen des abmeldenden Clients aus der Fan-Out-Liste der Eventgruppe.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Zu Beginn zerlegt <code>Sd</code> eine eingegangene Nachricht über den Selbstaufruf <code>disassembleIncomingMessage() :entries, options</code>.</li>\n<li>Über ein <code>alt</code>-Fragment (<code>alt over received entries</code>) wird sequenziell über die empfangenen Einträge verzweigt:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==FindService]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if entry is in Main Phase and entry is available</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>buildOfferServiceEntry()</code> wird aufgerufen.</li>\n<li><code>determineRequestResponseDelay(SdServerTimerRequestResponseMinDelay, SdServerTimerRequestResponseMaxDelay)</code> bestimmt die Verzögerung.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\"+delay)</code> reiht den Eintrag mit Verzögerung ein.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==SubscribeEventgroup]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if eventgroup entry is available</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>addClientToFanOut()</code> registriert den Client.</li>\n<li><code>buildSubscribeAckEntry()</code> erzeugt das Subscribe-Ack.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\")</code> reiht die Bestätigung ohne Verzögerung (<code>sendTime=\"now\"</code>) in die Sendewarteschlange ein.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==StopSubscribeEventgroup]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if client is subscribed</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>removeClientFromFanOut()</code> deregistriert den Client aus dem Fan-Out.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[else]</code>:</li>\n<li>Keine Aktion definiert (stilles Verwerfen / Übergehen nicht passender Einträge).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Spezifiziert das normative Reaktionsverhalten des SD-Servers auf FindService-, SubscribeEventgroup- und StopSubscribeEventgroup-Nachrichten.</li>\n<li>Die Antwort auf FindService erfordert die Berücksichtigung von Phasenbedingungen (Main Phase) und die Einhaltung eines parametrierten Jitters/Delays (<code>SdServerTimerRequestResponseMinDelay</code> bis <code>SdServerTimerRequestResponseMaxDelay</code>) zur Vermeidung von Botschaftskollisionen auf dem Netzwerk.</li>\n<li>Eventgruppen-Abonnements erfordern die Pflege von Fan-Out-Tabellen zur Laufzeit; Subscribe-Acks werden im Gegensatz zu OfferService-Antworten unmittelbar (<code>sendTime=\"now\"</code>) eingereiht. StopSubscribe führt zur Entfernung ohne Sendeantwort.</li>\n</ul>"}, {"id": "FIG-104ff9cbc68743f5", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Server-Antwortverhaltens im AUTOSAR-Basissoftwaremodul Service Discovery (<code>Sd</code>) innerhalb des AUTOSAR-Kommunikationsstacks (Classic Platform). Das Diagramm stellt die interne Verarbeitung empfangener SD-Nachrichten und die Vorbereitung von Antwortnachrichten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>«module» Sd</code>: AUTOSAR Service Discovery Basissoftwaremodul (zentrale aktive Lebenslinie, führt die Verarbeitungslogik aus).</li>\n<li><code>«module» SoAd</code>: Socket Adapter Basissoftwaremodul (passive Lebenslinie im Diagramm, an der keine Interaktionspfeile ansetzen oder enden).</li>\n<li>Interne Methoden / Selbstaufrufe auf <code>Sd</code>:</li>\n<li><code>disassembleIncomingMessage() :entries, options</code>: Dekodierung und Zerlegung der eingehenden SD-Botschaft in Einträge und Optionen.</li>\n<li><code>buildOfferServiceEntry()</code>: Erstellung eines OfferService-Eintrags.</li>\n<li><code>determineRequestResponseDelay(SdServerTimerRequestResponseMinDelay, SdServerTimerRequestResponseMaxDelay)</code>: Ermittlung der zufälligen oder parametrierten Antwortverzögerung.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\"+delay)</code>: Einreihen des OfferService in die Sendewarteschlange mit berechneter Verzögerung.</li>\n<li><code>addClientToFanOut()</code>: Hinzufügen des anfragenden Clients zur Fan-Out-Liste der Eventgruppe.</li>\n<li><code>buildSubscribeAckEntry()</code>: Erstellung eines SubscribeEventgroupAck-Eintrags.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\")</code>: Sofortiges Einreihen der Bestätigung in die Sendewarteschlange.</li>\n<li><code>removeClientFromFanOut()</code>: Entfernen des abmeldenden Clients aus der Fan-Out-Liste der Eventgruppe.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Zu Beginn zerlegt <code>Sd</code> eine eingegangene Nachricht über den Selbstaufruf <code>disassembleIncomingMessage() :entries, options</code>.</li>\n<li>Über ein <code>alt</code>-Fragment (<code>alt over received entries</code>) wird sequenziell über die empfangenen Einträge verzweigt:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==FindService]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if entry is in Main Phase and entry is available</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>buildOfferServiceEntry()</code> wird aufgerufen.</li>\n<li><code>determineRequestResponseDelay(SdServerTimerRequestResponseMinDelay, SdServerTimerRequestResponseMaxDelay)</code> bestimmt die Verzögerung.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\"+delay)</code> reiht den Eintrag mit Verzögerung ein.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==SubscribeEventgroup]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if eventgroup entry is available</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>addClientToFanOut()</code> registriert den Client.</li>\n<li><code>buildSubscribeAckEntry()</code> erzeugt das Subscribe-Ack.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\")</code> reiht die Bestätigung ohne Verzögerung (<code>sendTime=\"now\"</code>) in die Sendewarteschlange ein.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==StopSubscribeEventgroup]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if client is subscribed</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>removeClientFromFanOut()</code> deregistriert den Client aus dem Fan-Out.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[else]</code>:</li>\n<li>Keine Aktion definiert (stilles Verwerfen / Übergehen nicht passender Einträge).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Spezifiziert das normative Reaktionsverhalten des SD-Servers auf FindService-, SubscribeEventgroup- und StopSubscribeEventgroup-Nachrichten.</li>\n<li>Die Antwort auf FindService erfordert die Berücksichtigung von Phasenbedingungen (Main Phase) und die Einhaltung eines parametrierten Jitters/Delays (<code>SdServerTimerRequestResponseMinDelay</code> bis <code>SdServerTimerRequestResponseMaxDelay</code>) zur Vermeidung von Botschaftskollisionen auf dem Netzwerk.</li>\n<li>Eventgruppen-Abonnements erfordern die Pflege von Fan-Out-Tabellen zur Laufzeit; Subscribe-Acks werden im Gegensatz zu OfferService-Antworten unmittelbar (<code>sendTime=\"now\"</code>) eingereiht. StopSubscribe führt zur Entfernung ohne Sendeantwort.</li>\n</ul>"}, {"id": "FIG-0aa430a755942526", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Server-Antwortverhaltens im AUTOSAR-Basissoftwaremodul Service Discovery (<code>Sd</code>) innerhalb des AUTOSAR-Kommunikationsstacks (Classic Platform). Das Diagramm stellt die interne Verarbeitung empfangener SD-Nachrichten und die Vorbereitung von Antwortnachrichten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>«module» Sd</code>: AUTOSAR Service Discovery Basissoftwaremodul (zentrale aktive Lebenslinie, führt die Verarbeitungslogik aus).</li>\n<li><code>«module» SoAd</code>: Socket Adapter Basissoftwaremodul (passive Lebenslinie im Diagramm, an der keine Interaktionspfeile ansetzen oder enden).</li>\n<li>Interne Methoden / Selbstaufrufe auf <code>Sd</code>:</li>\n<li><code>disassembleIncomingMessage() :entries, options</code>: Dekodierung und Zerlegung der eingehenden SD-Botschaft in Einträge und Optionen.</li>\n<li><code>buildOfferServiceEntry()</code>: Erstellung eines OfferService-Eintrags.</li>\n<li><code>determineRequestResponseDelay(SdServerTimerRequestResponseMinDelay, SdServerTimerRequestResponseMaxDelay)</code>: Ermittlung der zufälligen oder parametrierten Antwortverzögerung.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\"+delay)</code>: Einreihen des OfferService in die Sendewarteschlange mit berechneter Verzögerung.</li>\n<li><code>addClientToFanOut()</code>: Hinzufügen des anfragenden Clients zur Fan-Out-Liste der Eventgruppe.</li>\n<li><code>buildSubscribeAckEntry()</code>: Erstellung eines SubscribeEventgroupAck-Eintrags.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\")</code>: Sofortiges Einreihen der Bestätigung in die Sendewarteschlange.</li>\n<li><code>removeClientFromFanOut()</code>: Entfernen des abmeldenden Clients aus der Fan-Out-Liste der Eventgruppe.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Zu Beginn zerlegt <code>Sd</code> eine eingegangene Nachricht über den Selbstaufruf <code>disassembleIncomingMessage() :entries, options</code>.</li>\n<li>Über ein <code>alt</code>-Fragment (<code>alt over received entries</code>) wird sequenziell über die empfangenen Einträge verzweigt:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==FindService]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if entry is in Main Phase and entry is available</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>buildOfferServiceEntry()</code> wird aufgerufen.</li>\n<li><code>determineRequestResponseDelay(SdServerTimerRequestResponseMinDelay, SdServerTimerRequestResponseMaxDelay)</code> bestimmt die Verzögerung.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\"+delay)</code> reiht den Eintrag mit Verzögerung ein.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==SubscribeEventgroup]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if eventgroup entry is available</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>addClientToFanOut()</code> registriert den Client.</li>\n<li><code>buildSubscribeAckEntry()</code> erzeugt das Subscribe-Ack.</li>\n<li><code>addToSendQueue(dest, entry, options, sendTime=\"now\")</code> reiht die Bestätigung ohne Verzögerung (<code>sendTime=\"now\"</code>) in die Sendewarteschlange ein.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[entry==StopSubscribeEventgroup]</code>:</li>\n<li>Innerhalb eines optionalen Blocks (<code>opt if client is subscribed</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>removeClientFromFanOut()</code> deregistriert den Client aus dem Fan-Out.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[else]</code>:</li>\n<li>Keine Aktion definiert (stilles Verwerfen / Übergehen nicht passender Einträge).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Spezifiziert das normative Reaktionsverhalten des SD-Servers auf FindService-, SubscribeEventgroup- und StopSubscribeEventgroup-Nachrichten.</li>\n<li>Die Antwort auf FindService erfordert die Berücksichtigung von Phasenbedingungen (Main Phase) und die Einhaltung eines parametrierten Jitters/Delays (<code>SdServerTimerRequestResponseMinDelay</code> bis <code>SdServerTimerRequestResponseMaxDelay</code>) zur Vermeidung von Botschaftskollisionen auf dem Netzwerk.</li>\n<li>Eventgruppen-Abonnements erfordern die Pflege von Fan-Out-Tabellen zur Laufzeit; Subscribe-Acks werden im Gegensatz zu OfferService-Antworten unmittelbar (<code>sendTime=\"now\"</code>) eingereiht. StopSubscribe führt zur Entfernung ohne Sendeantwort.</li>\n</ul>"}], "trans": [{"from": "FIG-a43c499d2ba1ab54", "to": "FIG-e268d6f2d1e8aab3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e268d6f2d1e8aab3", "to": "FIG-2593068811199b67", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2593068811199b67", "to": "FIG-104ff9cbc68743f5", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-104ff9cbc68743f5", "to": "FIG-0aa430a755942526", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
